import 'dart:io';import 'dart:convert';
void main(List<String>a){if(a.isEmpty||a[0]=='--help'){print('Usage: jsonl-stats FILE');exit(a.isEmpty?2:0);}var valid=0,invalid=0,blank=0;var types=<String,int>{};var n=0;for(final line in File(a[0]).readAsLinesSync()){n++;if(line.trim().isEmpty){blank++;continue;}try{var v=jsonDecode(line);var t=v==null?'null':v.runtimeType.toString();types[t]=(types[t]??0)+1;valid++;}catch(e){invalid++;if(invalid<=10)stderr.writeln('line $n: $e');}}print('lines=$n\nvalid=$valid\ninvalid=$invalid\nblank=$blank');types.forEach((k,v)=>print('$k=$v'));if(invalid>0)exit(1);}
